package com.jinloes.practice;
import java.util.Arrays;
import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: server weights, then task durations separated by semicolon, for example: [3, 3, 2]; [1, 2, 3, 2, 1, 2]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) {runInput(String.join(" ",args).trim());return;} assertThat(Solution.assignTasks(new int[]{3,3,2},new int[]{1,2,3,2,1,2})).as("Example 1").containsExactly(2,2,0,2,1,2); assertThat(Solution.assignTasks(new int[]{5},new int[]{2,1,3})).as("Example 2").containsExactly(0,0,0); System.out.println("Examples passed: 2"); } private static void runInput(String input) {try{String[] p=input.split(";",-1); if(p.length!=2)throw new IllegalArgumentException(); System.out.println(Arrays.toString(Solution.assignTasks(parseArray(p[0]),parseArray(p[1]))));}catch(RuntimeException e){System.out.println("Could not read \""+input+"\". "+USAGE);}} private static int[] parseArray(String text){String s=text.trim();if(!s.startsWith("[")||!s.endsWith("]"))throw new IllegalArgumentException("array");String b=s.substring(1,s.length()-1).trim();if(b.isEmpty())return new int[0];String[] parts=b.split(",");int[] a=new int[parts.length];for(int i=0;i<parts.length;i++)a[i]=Integer.parseInt(parts[i].trim());return a;} }

